  string fresh=Root("fresh");var data=UserData(fresh);var payloads=Prepare(fresh,catalog.Modules);string backup=Apply(fresh,payloads);var engine=Engine(fresh);
  Check(!File.Exists(Paths.Resolve(fresh,"Plugins/DynastyCOT.dll")),"No collection host installed");foreach(var p in payloads)Check(Paths.HashFile(Paths.Resolve(fresh,"Plugins/"+p.Module.FileName))==p.Release.DllSha256,"Exact released standalone DLL");Unchanged(fresh,data);
  Check(engine.Inspect(fresh).Plugins.Count==4&&engine.Inspect(fresh).Plugins.All(x=>x.Known),"All modules recognized");
  requests.Clear();var keep=engine.Install(fresh,Choices(payloads),new PreparedModule[0]);Check(keep.Operations.Count==0,"Already-current modules should be kept without reinstallation");Check(requests.Count==0,"Plan itself must not contact GitHub");
  var removal=engine.Remove(fresh,new[]{"GamedayAtmosphere"});string removedBackup=engine.Execute(removal,new Dictionary<string,string>(),s=>{});Check(!File.Exists(Paths.Resolve(fresh,"Plugins/GamedayAtmosphere.dll")),"Partial uninstall removes selected DLL");Check(File.Exists(Paths.Resolve(fresh,"Plugins/BeyondTheField.dll")),"Partial uninstall leaves other DLLs");Unchanged(fresh,data);Reject(()=>engine.Restore(fresh,backup),"Out-of-order restore must not overwrite newer state");engine.Restore(fresh,removedBackup);Check(File.Exists(Paths.Resolve(fresh,"Plugins/GamedayAtmosphere.dll")),"Partial uninstall rollback restores module");Unchanged(fresh,data);
  string caseBackup=engine.Execute(engine.Remove(fresh,new[]{"GamedayAtmosphere"}),new Dictionary<string,string>(),s=>{});Check(engine.Backups(fresh.ToUpperInvariant()).Any(x=>x.Directory.Equals(caseBackup,StringComparison.OrdinalIgnoreCase)),"Backup discovery ignores Windows path casing");engine.Restore(fresh.ToUpperInvariant(),caseBackup.ToUpperInvariant());Check(File.Exists(Paths.Resolve(fresh,"Plugins/GamedayAtmosphere.dll")),"Restore survives a differently cased MMC path");
