  string adopt=Root("drag-and-drop");Directory.CreateDirectory(Paths.Resolve(adopt,"Plugins"));File.Copy(payloads[0].Dll,Paths.Resolve(adopt,"Plugins/BeyondTheField.dll"));var a=Engine(adopt);var before=File.GetLastWriteTimeUtc(Paths.Resolve(adopt,"Plugins/BeyondTheField.dll"));var adoption=a.Install(adopt,Choices(payloads.Take(1)),new PreparedModule[0]);Check(adoption.Operations.All(x=>!x.Path.EndsWith(".dll")),"Adopting existing standalone doesn't rewrite its DLL");a.Execute(adoption,new Dictionary<string,string>(),s=>{});Check(File.GetLastWriteTimeUtc(Paths.Resolve(adopt,"Plugins/BeyondTheField.dll"))==before,"Adoption preserves DLL timestamp");
  string duplicate=Root("duplicates");Directory.CreateDirectory(Paths.Resolve(duplicate,"Plugins/old"));File.Copy(payloads[0].Dll,Paths.Resolve(duplicate,"Plugins/old/renamed.dll"));File.Copy(payloads[0].Dll,Paths.Resolve(duplicate,"Plugins/DynastyEnhancer.dll"));var d=Engine(duplicate);var dedup=d.Install(duplicate,Choices(payloads.Take(1)),payloads.Take(1));Check(dedup.Inventory.Plugins.Count==2,"Renamed and legacy copies recognized by assembly identity");d.Execute(dedup,new Dictionary<string,string>(),s=>{});Check(d.Inspect(duplicate).Plugins.Count==1&&File.Exists(Paths.Resolve(duplicate,"Plugins/BeyondTheField.dll")),"Duplicate loading prevented");
  string unknown=Root("unknown");Directory.CreateDirectory(Paths.Resolve(unknown,"Plugins"));byte[] altered=File.ReadAllBytes(payloads[0].Dll).Concat(new byte[]{1}).ToArray();File.WriteAllBytes(Paths.Resolve(unknown,"Plugins/BeyondTheField.dll"),altered);var u=Engine(unknown);var review=u.Install(unknown,Choices(payloads.Take(1)),payloads.Take(1));Reject(()=>u.Execute(review,new Dictionary<string,string>(),s=>{}),"Unknown plugin requires explicit exact-hash review");Check(Paths.HashFile(Paths.Resolve(unknown,"Plugins/BeyondTheField.dll"))==Paths.Hash(altered),"Refused review leaves files unchanged");var approvals=u.Review(review).ToDictionary(x=>x.Path,x=>x.Sha256);File.AppendAllText(Paths.Resolve(unknown,"Plugins/BeyondTheField.dll"),"changed after review");Reject(()=>u.Execute(review,approvals,s=>{}),"File changed since review must be rejected");File.WriteAllBytes(Paths.Resolve(unknown,"Plugins/BeyondTheField.dll"),altered);u.Execute(review,approvals,s=>{});Check(Paths.HashFile(Paths.Resolve(unknown,"Plugins/BeyondTheField.dll"))==payloads[0].Release.DllSha256,"Explicitly reviewed unknown copy replaced transactionally");
  string legacy=Root("old-cot");Legacy(legacy,true);var history=UserData(legacy);var l=Engine(legacy);Reject(()=>l.Install(legacy,Choices(payloads.Take(1)),payloads.Take(1)),"Old host can't be removed while dropping enabled modules");var migration=l.Install(legacy,Choices(payloads),payloads);Check(migration.Operations.Any(x=>x.Deferred),"Migration retains old matching runtime rollback snapshots");string migrated=l.Execute(migration,new Dictionary<string,string>(),s=>{});Check(!File.Exists(Paths.Resolve(legacy,"Plugins/DynastyCOT.dll"))&&l.Inspect(legacy).Plugins.Count==4,"Old COT migrated to four DLLs");Unchanged(legacy,history);
