   var item=support.GetEntry(operation.Path);if(item==null)continue;using(var input=item.Open())using(var output=new MemoryStream()){input.CopyTo(output);var bytes=output.ToArray();if(Paths.Hash(bytes)!=operation.Before&&catalog.Programs.Any(x=>x.Path==operation.Path&&x.Sha256==Paths.Hash(bytes))){deferred=operation;program=bytes;break;}}
