  var futureBytes=Encoding.UTF8.GetBytes("verified future runtime fixture; never executed");var futureZip=Zip(bm.FileName,File.ReadAllBytes(args[2]));future.ArchiveBytes=futureZip.Length;future.ArchiveSha256=Paths.Hash(futureZip);future.DllSha256=Paths.HashFile(args[2]);remote[future.ArchiveUrl]=futureZip;remote[future.ProofUrl]=Json.Bytes(new{name=bm.Id,version=future.Version,archiveSha256=future.ArchiveSha256,dllSha256=future.DllSha256,payload=new Dictionary<string,string>{{deferred.Path,Paths.Hash(futureBytes)}}});
  var mislabeled=Copy(future);mislabeled.Version="9.9.8";mislabeled.Tag="v9.9.8";mislabeled.ArchiveName="BeyondTheField-9.9.8.zip";mislabeled.ArchiveUrl=future.ArchiveUrl.Replace("9.9.9","9.9.8");mislabeled.ProofUrl=future.ProofUrl.Replace("9.9.9","9.9.8");remote[mislabeled.ArchiveUrl]=futureZip;remote[mislabeled.ProofUrl]=Json.Bytes(new{name=bm.Id,version=mislabeled.Version,archiveSha256=mislabeled.ArchiveSha256,dllSha256=mislabeled.DllSha256});Reject(()=>Client(legacy).Prepare(bm,mislabeled,Path.Combine(parent,"MislabeledCache"),CancellationToken.None,s=>{}),"Valid ZIP/proof hashes cannot hide the wrong DLL version");
  var futurePayload=Client(legacy).Prepare(bm,future,Path.Combine(parent,"FutureCache"),CancellationToken.None,s=>{});Check(futurePayload.Programs.Any(x=>x.Path==deferred.Path&&x.Sha256==Paths.Hash(futureBytes)),"Verified future program hashes captured without code execution");
  string futureBackup=l.Execute(l.Install(legacy,new Dictionary<string,ModuleRelease>{{bm.Id,future}},new[]{futurePayload}),new Dictionary<string,string>(),s=>{});File.WriteAllBytes(Paths.Resolve(legacy,deferred.Path),futureBytes);Check(!catalog.Programs.Any(x=>x.Sha256==Paths.Hash(futureBytes)),"Future cache hash is genuinely outside shipped catalog");l.Restore(legacy,futureBackup);Check(Paths.HashFile(Paths.Resolve(legacy,"Plugins/BeyondTheField.dll"))==bm.Current.DllSha256,"Independent future module rollback restores prior DLL");
  l.Restore(legacy,migrated);Check(File.Exists(Paths.Resolve(legacy,"Plugins/DynastyCOT.dll"))&&l.Inspect(legacy).Plugins.Count==1,"Rollback restores older COT host without duplicate standalone DLLs");Check(Paths.HashFile(Paths.Resolve(legacy,deferred.Path))==deferred.Before,"Matching old program restored after known support-file change");Unchanged(legacy,history);
  string partialOld=Root("partial-old");Legacy(partialOld,false);var pe=Engine(partialOld);pe.Execute(pe.Remove(partialOld,new[]{"GamedayAtmosphere"}),new Dictionary<string,string>(),s=>{});Check(!File.Exists(Paths.Resolve(partialOld,"Plugins/DynastyCOT.dll")),"Removing final enabled legacy module retires old host");
  string tamper=Root("tampered-backup");Apply(tamper,payloads.Take(1).ToList());var te=Engine(tamper);string transaction=te.Execute(te.Remove(tamper,new[]{"BeyondTheField"}),new Dictionary<string,string>(),s=>{});var j=Json.Read<Journal>(Path.Combine(transaction,"transaction.json"));File.AppendAllText(Path.Combine(transaction,j.Operations.First(x=>x.Before!=null).Backup),"bad");Reject(()=>te.Restore(tamper,transaction),"Tampered backup cannot be restored");Check(!File.Exists(Paths.Resolve(tamper,"Plugins/BeyondTheField.dll")),"Tampered restore preflights before changing any files");
  string hostile=Root("hostile-journal");string hostileBackup=Apply(hostile,payloads.Take(1).ToList());var hostileJournal=Json.Read<Journal>(Path.Combine(hostileBackup,"transaction.json"));hostileJournal.Operations[0].Path="COT-Runtime/DynastyEnhancer/RuntimeHistory/42/history.json";File.WriteAllBytes(Path.Combine(hostileBackup,"transaction.json"),Json.Bytes(hostileJournal));Reject(()=>Engine(hostile).Restore(hostile,hostileBackup),"A journal cannot claim history as managed payload");
